#!/usr/bin/env bash
set -euo pipefail

# Test: branch-guard sibling-repo exemption + plan-mode soften + /save PR dedupe
# Generated by /qa on 2026-04-18
# Covers:
#   .claude/hooks/branch-guard.sh
#   .claude/skills/save/SKILL.md (dedupe pattern via doc inspection)
#   .codex/skills/save/SKILL.md (clean-tree PR publication guard)
#   .claude/skills/wrap/SKILL.md (session_duration_ms derivation)

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$SCRIPT_DIR/.claude/hooks/branch-guard.sh"
SAVE_MD="$SCRIPT_DIR/.claude/skills/save/SKILL.md"
CODEX_SAVE_MD="$SCRIPT_DIR/.codex/skills/save/SKILL.md"
WRAP_MD="$SCRIPT_DIR/.claude/skills/wrap/SKILL.md"
CLAUDE_MD="$SCRIPT_DIR/CLAUDE.md"

PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    → $2"; }

echo "Testing: branch-guard + /save dedupe + /wrap duration"
echo

# ─────────────────────────────────────────────────────────
# branch-guard.sh — runtime behavior on a real develop branch
# ─────────────────────────────────────────────────────────

echo "── branch-guard runtime ──"

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
cd "$TMP"
git init -q
git checkout -q -b develop
git -c user.email=t@t -c user.name=t commit --allow-empty -q -m init
export CLAUDE_PROJECT_DIR="$TMP"

# 1) EnterPlanMode on develop must now exit 0 (softened)
set +e
echo '{"tool_name":"EnterPlanMode","tool_input":{}}' | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "EnterPlanMode on develop → allowed (soften fix)"
else
  fail "EnterPlanMode on develop → blocked with exit $rc" "expected 0"
fi

# 2) Write to sibling dir outside PROJECT_DIR must exit 0 (sibling-repo fix)
SIBLING=$(mktemp -d)
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$SIBLING/file.md\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
rm -rf "$SIBLING"
if [ "$rc" -eq 0 ]; then
  pass "Write to sibling repo (outside PROJECT_DIR) on develop → allowed"
else
  fail "Write to sibling repo on develop → blocked with exit $rc" "expected 0 after sibling-repo exemption"
fi

# 3) Write to a project-internal path on develop must block (exit 2)
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/src/f.py\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 2 ]; then
  pass "Write to project-internal path on develop → blocked (exit 2)"
else
  fail "Write to project-internal path on develop → exit $rc" "expected 2"
fi

# 4) Block message mentions AskUserQuestion
set +e
MSG=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/src/f.py\"}}" | bash "$HOOK" 2>&1 >/dev/null)
set -e
if echo "$MSG" | grep -q "AskUserQuestion"; then
  pass "block message instructs Claude to use AskUserQuestion"
else
  fail "block message missing AskUserQuestion directive" "got: $MSG"
fi
if echo "$MSG" | grep -q "create the branch automatically" &&
   ! echo "$MSG" | grep -q "Ask the user how to proceed"; then
  pass "clear-topic path auto-branches without a routine Git prompt"
else
  fail "block message still interrupts for routine branch permission" "got: $MSG"
fi

# 5) Write to .claude/ on develop must still be allowed (pre-existing exemption intact)
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/.claude/foo.md\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass ".claude/ exemption on develop → still allowed"
else
  fail ".claude/ exemption broke" "exit $rc"
fi

# 6) The documented consent command must never be blocked by the guard itself
set +e
echo "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"echo 'develop' > .egregore-branch-consent\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "protected-branch consent command → allowed"
else
  fail "consent command blocked itself" "exit $rc"
fi

# 7) Memory-only shell preparation must not force a project branch
set +e
echo "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"mkdir -p memory/knowledge/harvests/test\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "memory-only shell preparation on develop → allowed"
else
  fail "memory-only shell preparation unexpectedly blocked" "exit $rc"
fi

# 8) On a non-protected branch the hook must short-circuit to allow everything
git checkout -q -b dev/test/topic
set +e
echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$TMP/src/f.py\"}}" | bash "$HOOK" >/dev/null 2>&1
rc=$?
set -e
if [ "$rc" -eq 0 ]; then
  pass "on non-protected branch → hook short-circuits (allow)"
else
  fail "non-protected branch unexpectedly blocked" "exit $rc"
fi

cd "$SCRIPT_DIR"

# ─────────────────────────────────────────────────────────
# /save — dedupe pattern present in both flows
# ─────────────────────────────────────────────────────────

echo
echo "── /save PR dedupe ──"

# Codex must not equate a clean tree with a fully published branch. A task
# branch can be clean because an attendant already committed it while still
# lacking the integration PR that makes the work mergeable.
if grep -qE 'git rev-list --count.*origin/develop\.\.HEAD' "$CODEX_SAVE_MD" &&
   grep -qE 'gh pr list --head.*--base develop.*--state open' "$CODEX_SAVE_MD"; then
  pass "Codex /save checks committed work and PR state before stopping"
else
  fail "Codex /save can still stop on a clean branch with no PR"
fi
if grep -q 'clean working tree alone' "$CODEX_SAVE_MD" &&
   grep -q 'create the missing PR' "$CODEX_SAVE_MD"; then
  pass "Codex /save continues clean-but-unpublished branches through the bridge"
else
  fail "Codex /save missing clean-but-unpublished continuation rule"
fi

# Hub flow: dedupe via gh pr list --head --state open, before gh pr create
if grep -qE 'gh pr list --head.*--state open.*--json number,baseRefName' "$SAVE_MD"; then
  pass "/save hub flow: gh pr list dedupe present"
else
  fail "/save hub flow missing dedupe query"
fi

# Managed-repo flow: same pattern, scoped with --repo
if grep -qE 'gh pr list --repo.*--head.*--state open.*--json number,baseRefName' "$SAVE_MD"; then
  pass "/save managed-repo flow: gh pr list dedupe present"
else
  fail "/save managed-repo flow missing dedupe query"
fi

# Retarget path: gh pr edit ... --base used when existing PR has wrong base
if grep -qE 'gh pr edit.*--base' "$SAVE_MD"; then
  pass "/save retargets existing PR with wrong base (no duplicate)"
else
  fail "/save missing retarget path — could still create duplicate"
fi

# No orphan `gh pr create` in operational code blocks without a dedupe check.
# Only count lines that look like actual shell commands (indented inside a code
# block — `    gh pr create` or `     gh pr create`), not prose mentions of
# the command name. Every such command must be preceded within 40 lines by a
# `gh pr list`.
awk '
  /gh pr list/ { last_list = NR }
  /^    *gh pr create/ {
    if (last_list == 0 || NR - last_list > 40) {
      print NR ":" $0
    }
  }
' "$SAVE_MD" | grep -v "^$" > /tmp/unguarded.txt || true
UNGUARDED=$(grep -v "^$" /tmp/unguarded.txt 2>/dev/null | wc -l | tr -d ' ')
# Example output blocks near the end still include bare `gh pr create` in
# illustrative sample console output. Allow a small quota for those.
if [ "$UNGUARDED" -le 4 ]; then
  pass "no unguarded gh pr create in operational code blocks (allowing $UNGUARDED in illustrative examples)"
else
  fail "found $UNGUARDED unguarded gh pr create calls in code blocks" "$(cat /tmp/unguarded.txt)"
fi

# ─────────────────────────────────────────────────────────
# /wrap — session_duration_ms derivation present
# ─────────────────────────────────────────────────────────

echo
echo "── /wrap duration computation ──"

if grep -qE '\.egregore-session-id' "$WRAP_MD" && grep -qE 'DURATION_MS=' "$WRAP_MD"; then
  pass "/wrap derives session_duration_ms from session id"
else
  fail "/wrap still leaves session_duration_ms as literal 0"
fi

# Test the actual sed/awk pipeline in isolation
SID="20260418T043308-entropyeq-44014"
START_TS=$(echo "$SID" | sed -E 's/^([0-9]{8})T([0-9]{6}).*/\1 \2/' | awk '{printf "%s-%s-%s %s:%s:%s", substr($1,1,4),substr($1,5,2),substr($1,7,2),substr($2,1,2),substr($2,3,2),substr($2,5,2)}')
if [ "$START_TS" = "2026-04-18 04:33:08" ]; then
  pass "sid parser produces correct ISO timestamp"
else
  fail "sid parser produced: $START_TS" "expected: 2026-04-18 04:33:08"
fi

# macOS (BSD) + Linux (GNU) date fallback produces an epoch
START_EPOCH=$(date -j -u -f '%Y-%m-%d %H:%M:%S' "$START_TS" +%s 2>/dev/null || date -u -d "$START_TS" +%s 2>/dev/null)
if [ -n "$START_EPOCH" ] && [ "$START_EPOCH" -gt 0 ] 2>/dev/null; then
  pass "date parser produces epoch ($START_EPOCH)"
else
  fail "date parser failed on macOS+Linux fallback"
fi

# Edge case: malformed SID must not break — skill should gate parsing on regex match
# The skill's actual guard is `if [[ "$SID" =~ ^[0-9]{8}T[0-9]{6}- ]]`, then defaults DURATION_MS=0.
if grep -qE 'DURATION_MS=0' "$WRAP_MD" && grep -qE 'SID.*=~' "$WRAP_MD"; then
  pass "/wrap guards malformed SID (regex gate + DURATION_MS=0 default)"
else
  fail "/wrap does not guard malformed SID" "arithmetic could break when session id missing or malformed"
fi

# ─────────────────────────────────────────────────────────
# CLAUDE.md — branch-guard protocol section added
# ─────────────────────────────────────────────────────────

echo
echo "── CLAUDE.md protocol ──"

if grep -q "Branch-guard protocol" "$CLAUDE_MD"; then
  pass "CLAUDE.md has 'Branch-guard protocol' section"
else
  fail "CLAUDE.md missing 'Branch-guard protocol' section"
fi

if grep -q "Plan mode is \*\*not\*\* blocked" "$CLAUDE_MD"; then
  pass "CLAUDE.md documents plan-mode soften"
else
  fail "CLAUDE.md does not document plan-mode soften"
fi

# ─────────────────────────────────────────────────────────
# Summary
# ─────────────────────────────────────────────────────────

echo
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
